import { finalize, tap } from "rxjs";
/** An operator that claims the latest event with the database */
export function claimLatest(claims) {
    return (source) => {
        let latest = undefined;
        return source.pipe(tap((event) => {
            // only update if the event changed
            if (latest !== event) {
                // remove old claim
                if (latest)
                    claims.removeClaim(latest);
                // claim new event
                if (event)
                    claims.claim(event);
                // update state
                latest = event;
            }
        }), finalize(() => {
            // remove latest claim
            if (latest)
                claims.removeClaim(latest);
        }));
    };
}
